1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Tetris</title>
7	<style>
8	  * { box-sizing: border-box; }
9	  [hidden] { display: none !important; }
10	  body {
11	    margin: 0;
12	    min-height: 100vh;
13	    display: flex;
14	    align-items: center;
15	    justify-content: center;
16	    background: #111827;
17	    color: #e5e7eb;
18	    font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
19	  }
20	  .game { display: flex; gap: 24px; align-items: flex-start; padding: 16px; }
21	  .board-wrap { position: relative; }
22	  .board {
23	    display: grid;
24	    grid-template-columns: repeat(10, 28px);
25	    grid-template-rows: repeat(20, 28px);
26	    gap: 1px;
27	    padding: 1px;
28	    background: #1f2937;
29	    border: 2px solid #374151;
30	  }
31	  .cell { width: 28px; height: 28px; background-color: #0b1020; }
32	  .mini {
33	    display: grid;
34	    grid-template-columns: repeat(4, 16px);
35	    grid-template-rows: repeat(2, 16px);
36	    gap: 1px;
37	  }
38	  .mini-cell { width: 16px; height: 16px; background-color: transparent; }
39	  .p-I { background-color: #22d3ee; }
40	  .p-O { background-color: #facc15; }
41	  .p-T { background-color: #a855f7; }
42	  .p-S { background-color: #22c55e; }
43	  .p-Z { background-color: #ef4444; }
44	  .p-J { background-color: #3b82f6; }
45	  .p-L { background-color: #f97316; }
46	  .panel { width: 160px; }
47	  .stat { margin-bottom: 14px; }
48	  .stat .label { font-size: 12px; text-transform: uppercase; letter-spacing: 0.08em; color: #9ca3af; }
49	  .stat .value { font-size: 24px; font-weight: 600; font-variant-numeric: tabular-nums; }
50	  .help { font-size: 12px; color: #9ca3af; line-height: 1.6; margin-top: 12px; }
51	  .overlay {
52	    position: absolute;
53	    inset: 0;
54	    display: flex;
55	    flex-direction: column;
56	    align-items: center;
57	    justify-content: center;
58	    background: rgba(17, 24, 39, 0.8);
59	    font-size: 22px;
60	    font-weight: 600;
61	  }
62	  .overlay small { font-size: 13px; font-weight: 400; margin-top: 8px; color: #d1d5db; }
63	</style>
64	</head>
65	<body>
66	<div class="game">
67	  <div class="board-wrap">
68	    <div class="board" id="board" data-testid="board"></div>
69	    <div class="overlay" id="overlay" data-testid="game-over" hidden>Game over<small>Press Enter to play again</small></div>
70	  </div>
71	  <div class="panel">
72	    <div class="stat"><div class="label">Score</div><div class="value" data-testid="score" id="score">0</div></div>
73	    <div class="stat"><div class="label">Level</div><div class="value" data-testid="level" id="level">1</div></div>
74	    <div class="stat"><div class="label">Lines</div><div class="value" data-testid="lines" id="lines">0</div></div>
75	    <div class="stat"><div class="label">Next</div><div id="next" data-testid="next-piece"></div></div>
76	    <div class="help">
77	      ← → move<br>
78	      ↑ rotate<br>
79	      ↓ soft drop<br>
80	      Space hard drop<br>
81	      Enter new game
82	    </div>
83	  </div>
84	</div>
85	<script>
86	(function () {
87	  "use strict";
88	
89	  var ROWS = 20;
90	  var COLS = 10;
91	  var PREVIEW = 1; // [REQ-006] show only the next piece
92	  var TYPES = ["I", "O", "T", "S", "Z", "J", "L"];
93	
94	  // Spawn orientation of each piece inside its rotation box.
95	  var SHAPES = {
96	    I: ["....", "IIII", "....", "...."],
97	    O: ["OO", "OO"],
98	    T: [".T.", "TTT", "..."],
99	    S: [".SS", "SS.", "..."],
100	    Z: ["ZZ.", ".ZZ", "..."],
101	    J: ["J..", "JJJ", "..."],
102	    L: ["..L", "LLL", "..."]
103	  };
104	
105	  // Scoring (decision): points for rows cleared at once, times level. Clearing rows
106	  // together always beats clearing them one at a time. Soft drop 1 per cell, hard drop 2.
107	  var LINE_POINTS = [0, 100, 300, 500, 800];
108	  var SOFT_DROP_POINTS = 1;
109	  var HARD_DROP_POINTS = 2;
110	
111	  var state = {
112	    board: [],      // ROWS arrays of COLS chars: "." or a piece letter
113	    current: null,  // { type, matrix, row, col }
114	    next: [],
115	    bag: [],
116	    score: 0,
117	    level: 1,
118	    lines: 0,
119	    status: "running"
120	  };
121	
122	  var timer = null;
123	
124	  // ---------- pieces ----------
125	
126	  function isType(t) { return TYPES.indexOf(t) !== -1; }
127	
128	  function randomType() {
129	    if (state.bag.length === 0) {
130	      var bag = TYPES.slice();
131	      for (var i = bag.length - 1; i > 0; i--) {
132	        var j = Math.floor(Math.random() * (i + 1));
133	        var tmp = bag[i]; bag[i] = bag[j]; bag[j] = tmp;
134	      }
135	      state.bag = bag;
136	    }
137	    return state.bag.pop();
138	  }
139	
140	  function cleanQueue(queue) {
141	    if (!Array.isArray(queue)) return [];
142	    return queue.map(function (t) { return String(t).toUpperCase(); }).filter(isType);
143	  }
144	
145	  function fillPreview() {
146	    while (state.next.length < PREVIEW) state.next.push(randomType());
147	  }
148	
149	  function makeMatrix(type) {
150	    return SHAPES[type].map(function (r) { return r.split(""); });
151	  }
152	
153	  function pieceCells(piece) {
154	    var cells = [];
155	    for (var r = 0; r < piece.matrix.length; r++) {
156	      for (var c = 0; c < piece.matrix[r].length; c++) {
157	        if (piece.matrix[r][c] !== ".") cells.push([piece.row + r, piece.col + c]);
158	      }
159	    }
160	    return cells;
161	  }
162	
163	  function fits(matrix, row, col) {
164	    for (var r = 0; r < matrix.length; r++) {
165	      for (var c = 0; c < matrix[r].length; c++) {
166	        if (matrix[r][c] === ".") continue;
167	        var br = row + r, bc = col + c;
168	        if (br < 0 || br >= ROWS || bc < 0 || bc >= COLS) return false;
169	        if (state.board[br][bc] !== ".") return false;
170	      }
171	    }
172	    return true;
173	  }
174	
175	  // [REQ-001] [REQ-004] Spawn the next piece; the game ends if it has nowhere to go.
176	  function spawn() {
177	    var type = state.next.length ? state.next.shift() : randomType();
178	    fillPreview();
179	    var matrix = makeMatrix(type);
180	    var top = 0;
181	    while (matrix[top].every(function (ch) { return ch === "."; })) top++;
182	    var piece = {
183	      type: type,
184	      matrix: matrix,
185	      row: -top,
186	      col: Math.floor((COLS - matrix[0].length) / 2),
187	      lockTicks: 0,
188	      lockResets: 0
189	    };
190	    if (!fits(piece.matrix, piece.row, piece.col)) {
191	      state.current = null;
192	      state.status = "gameover";
193	      stopTimer();
194	      return;
195	    }
196	    state.current = piece;
197	  }
198	
199	  // ---------- core rules ----------
200	
201	  // [REQ-003] Remove full rows, drop the rest, score by rows cleared at once times level.
202	  function clearLines() {
203	    var kept = state.board.filter(function (row) {
204	      return row.some(function (ch) { return ch === "."; });
205	    });
206	    var cleared = ROWS - kept.length;
207	    while (kept.length < ROWS) kept.unshift(emptyRow());
208	    state.board = kept;
209	    if (cleared > 0) {
210	      state.score += LINE_POINTS[cleared] * state.level;
211	      state.lines += cleared;
212	      state.level = Math.floor(state.lines / 10) + 1;
213	    }
214	  }
215	
216	  // [REQ-001] Lock the falling piece into the board, clear lines, spawn the next one.
217	  function lockPiece() {
218	    var p = state.current;
219	    pieceCells(p).forEach(function (cell) {
220	      state.board[cell[0]][cell[1]] = p.type;
221	    });
222	    state.current = null;
223	    clearLines();
224	    spawn();
225	  }
226	
227	  function tryMove(dr, dc) {
228	    var p = state.current;
229	    if (!p || !fits(p.matrix, p.row + dr, p.col + dc)) return false;
230	    p.row += dr;
231	    p.col += dc;
232	    return true;
233	  }
234	
235	  // Lock rule (DEC): a gravity step that cannot move the piece down counts one tick of
236	  // lock delay; the piece locks on the LOCK_DELAY-th such tick. A left/right move while
237	  // resting restarts the delay, at most MAX_LOCK_RESETS times per piece. A soft drop on a
238	  // resting piece restarts it too, from the same budget.
239	  var LOCK_DELAY = 2;
240	  var MAX_LOCK_RESETS = 3;
241	
242	  function isResting(p) {
243	    return !fits(p.matrix, p.row + 1, p.col);
244	  }
245	
246	  // [REQ-002] [REQ-005] Restart the lock delay if the piece has restarts left.
247	  function restartLockDelay(p) {
248	    if (p.lockResets < MAX_LOCK_RESETS) {
249	      p.lockResets++;
250	      p.lockTicks = 0;
251	    }
252	  }
253	
254	  // [REQ-002] One gravity step: fall one row, or count a tick of lock delay.
255	  // Used by the real timer, by tick(n) and by soft drop. Returns true if the piece fell.
256	  function gravityStep() {
257	    if (state.status !== "running" || !state.current) return false;
258	    var p = state.current;
259	    if (tryMove(1, 0)) {
260	      p.lockTicks = 0;
261	      return true;
262	    }
263	    p.lockTicks++;
264	    if (p.lockTicks >= LOCK_DELAY) lockPiece();
265	    return false;
266	  }
267	
268	  // [REQ-002] Sideways move; restarts the lock delay if the piece was resting.
269	  function shift(dc) {
270	    var p = state.current;
271	    var resting = isResting(p);
272	    if (!tryMove(0, dc)) return;
273	    if (resting) restartLockDelay(p);
274	  }
275	
276	  // [REQ-003] [REQ-005] Soft drop: fall one row for a point. On a resting piece it scores
277	  // nothing and restarts the lock delay like a sideways move, instead of counting a tick.
278	  function softDrop() {
279	    var p = state.current;
280	    if (isResting(p)) {
281	      restartLockDelay(p);
282	      return;
283	    }
284	    tryMove(1, 0);
285	    p.lockTicks = 0;
286	    state.score += SOFT_DROP_POINTS;
287	  }
288	
289	  // [REQ-002] Clockwise rotation with sideways kicks; refused if nothing fits.
290	  function rotate() {
291	    var p = state.current;
292	    if (!p) return;
293	    var size = p.matrix.length;
294	    var rotated = [];
295	    for (var r = 0; r < size; r++) {
296	      rotated.push([]);
297	      for (var c = 0; c < size; c++) rotated[r].push(p.matrix[size - 1 - c][r]);
298	    }
299	    var kicks = [0, -1, 1, -2, 2];
300	    for (var i = 0; i < kicks.length; i++) {
301	      if (fits(rotated, p.row, p.col + kicks[i])) {
302	        p.matrix = rotated;
303	        p.col += kicks[i];
304	        return;
305	      }
306	    }
307	  }
308	
309	  // [REQ-001] [REQ-003] Player actions; soft and hard drop score per cell moved down.
310	  function input(action) {
311	    if (state.status !== "running" || !state.current) return;
312	    switch (action) {
313	      case "left": shift(-1); break;
314	      case "right": shift(1); break;
315	      case "softDrop": softDrop(); break;
316	      case "hardDrop":
317	        var dropped = 0;
318	        while (tryMove(1, 0)) dropped++;
319	        state.score += dropped * HARD_DROP_POINTS;
320	        lockPiece();
321	        break;
322	      case "rotate":
323	      case "rotateCW": rotate(); break;
324	      default: return;
325	    }
326	    render();
327	    restartTimerIfNeeded();
328	  }
329	
330	  // ---------- timer ----------
331	
332	  function gravityInterval() {
333	    return Math.max(100, 1000 - (state.level - 1) * 90);
334	  }
335	
336	  function stopTimer() {
337	    if (timer !== null) { clearTimeout(timer); timer = null; }
338	  }
339	
340	  function startTimer() {
341	    stopTimer();
342	    if (state.status !== "running") return;
343	    timer = setTimeout(function () {
344	      timer = null;
345	      gravityStep();
346	      render();
347	      startTimer();
348	    }, gravityInterval());
349	  }
350	
351	  function restartTimerIfNeeded() {
352	    if (state.status === "running" && timer === null) startTimer();
353	  }
354	
355	  // ---------- setup ----------
356	
357	  function emptyRow() {
358	    var row = [];
359	    for (var c = 0; c < COLS; c++) row.push(".");
360	    return row;
361	  }
362	
363	  // [REQ-001] Start a fresh game, optionally with a fixed piece order.
364	  function newGame(queue) {
365	    state.board = [];
366	    for (var r = 0; r < ROWS; r++) state.board.push(emptyRow());
367	    state.bag = [];
368	    state.score = 0;
369	    state.level = 1;
370	    state.lines = 0;
371	    state.status = "running";
372	    state.current = null;
373	    state.next = cleanQueue(queue);
374	    fillPreview();
375	    spawn();
376	    render();
377	    startTimer();
378	  }
379	
380	  // ---------- rendering (synchronous) ----------
381	
382	  var boardEl = document.getElementById("board");
383	  var nextEl = document.getElementById("next");
384	  var scoreEl = document.getElementById("score");
385	  var levelEl = document.getElementById("level");
386	  var linesEl = document.getElementById("lines");
387	  var overlayEl = document.getElementById("overlay");
388	  var cellEls = [];
389	
390	  (function buildBoard() {
391	    for (var r = 0; r < ROWS; r++) {
392	      cellEls.push([]);
393	      for (var c = 0; c < COLS; c++) {
394	        var el = document.createElement("div");
395	        el.className = "cell";
396	        el.setAttribute("data-testid", "cell");
397	        el.setAttribute("data-row", String(r));
398	        el.setAttribute("data-col", String(c));
399	        el.setAttribute("data-filled", "false");
400	        el.setAttribute("data-piece", "");
401	        boardEl.appendChild(el);
402	        cellEls[r].push(el);
403	      }
404	    }
405	  })();
406	
407	  function paintCell(el, type) {
408	    el.className = type ? "cell p-" + type : "cell";
409	    el.setAttribute("data-filled", type ? "true" : "false");
410	    el.setAttribute("data-piece", type || "");
411	  }
412	
413	  // [REQ-004] [REQ-006] The next piece only, coloured as on the board.
414	  function renderPreview() {
415	    nextEl.textContent = "";
416	    state.next.slice(0, PREVIEW).forEach(function (type) {
417	      var grid = document.createElement("div");
418	      grid.className = "mini";
419	      grid.setAttribute("data-testid", "next-piece-item");
420	      grid.setAttribute("data-piece", type);
421	      var rows = SHAPES[type].filter(function (r) { return r.indexOf(type) !== -1; });
422	      for (var r = 0; r < 2; r++) {
423	        for (var c = 0; c < 4; c++) {
424	          var cell = document.createElement("div");
425	          var ch = rows[r] ? rows[r].charAt(c) : ".";
426	          cell.className = ch === type ? "mini-cell p-" + type : "mini-cell";
427	          grid.appendChild(cell);
428	        }
429	      }
430	      nextEl.appendChild(grid);
431	    });
432	  }
433	
434	  // [REQ-001] Draw the whole game state into the DOM, immediately.
435	  function render() {
436	    var drawn = state.board.map(function (row) { return row.slice(); });
437	    if (state.current) {
438	      var type = state.current.type;
439	      pieceCells(state.current).forEach(function (cell) {
440	        drawn[cell[0]][cell[1]] = type;
441	      });
442	    }
443	    for (var r = 0; r < ROWS; r++) {
444	      for (var c = 0; c < COLS; c++) {
445	        var ch = drawn[r][c];
446	        paintCell(cellEls[r][c], ch === "." ? "" : ch);
447	      }
448	    }
449	    scoreEl.textContent = String(state.score);
450	    levelEl.textContent = String(state.level);
451	    linesEl.textContent = String(state.lines);
452	    overlayEl.hidden = state.status !== "gameover";
453	    renderPreview();
454	  }
455	
456	  // ---------- keyboard ----------
457	
458	  document.addEventListener("keydown", function (e) {
459	    var map = {
460	      ArrowLeft: "left",
461	      ArrowRight: "right",
462	      ArrowDown: "softDrop",
463	      ArrowUp: "rotateCW",
464	      " ": "hardDrop"
465	    };
466	    if (e.key === "Enter") {
467	      e.preventDefault();
468	      newGame();
469	      return;
470	    }
471	    if (map[e.key]) {
472	      e.preventDefault();
473	      input(map[e.key]);
474	    }
475	  });
476	
477	  // ---------- test control surface ----------
478	
479	  // [REQ-001]
480	  window.__tetris = {
481	    newGame: function (queue) { newGame(queue); },
482	    setQueue: function (queue) {
483	      state.next = cleanQueue(queue);
484	      fillPreview();
485	      render();
486	    },
487	    setBoard: function (rows) {
488	      var board = [];
489	      for (var r = 0; r < ROWS; r++) {
490	        var line = rows && typeof rows[r] === "string" ? rows[r] : "";
491	        var row = [];
492	        for (var c = 0; c < COLS; c++) {
493	          var ch = line.charAt(c);
494	          row.push(isType(ch) ? ch : ".");
495	        }
496	        board.push(row);
497	      }
498	      state.board = board;
499	      render();
500	    },
501	    tick: function (n) {
502	      var steps = n === undefined ? 1 : n;
503	      for (var i = 0; i < steps; i++) gravityStep();
504	      render();
505	    },
506	    input: function (action) { input(action); },
507	    getBoard: function () {
508	      return state.board.map(function (row) { return row.join(""); });
509	    },
510	    getState: function () {
511	      return {
512	        current: state.current
513	          ? { type: state.current.type, cells: pieceCells(state.current) }
514	          : null,
515	        next: state.next.slice(),
516	        score: state.score,
517	        level: state.level,
518	        lines: state.lines,
519	        status: state.status
520	      };
521	    }
522	  };
523	
524	  newGame();
525	})();
526	</script>
527	</body>
528	</html>
